/**
 * GLOBAL KPI MASTER LIST — 1000+ KPI
 * Block M: Chief Data Officer
 * 
 * Complete structured inventory of all measurable indicators.
 * If data exists → KPI. If it affects society → KPI.
 */

export interface KpiMasterEntry {
  id: string;
  name: string;
  definition: string;
  unit: string;
  direction: 'higher_better' | 'lower_better' | 'neutral';
  preferred_sources: string[];
  geo_levels_supported: string[];
  demographic_dimensions: string[];
  update_frequency: string;
  confidence_rules: { min_sample: number };
}

export type KpiDomain = 'health' | 'economy' | 'workforce' | 'education' | 'demographics' | 'crime' | 'housing' | 'energy' | 'infrastructure' | 'environment' | 'digital' | 'governance';

